import { test, expect } from '@playwright/test';

test.describe('Search Input Focus on Keyboard Slash', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should focus search input when pressing / on keyboard', async ({ page }) => {
    // Verify search input is visible and not focused initially
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).not.toBeFocused();

    // Press / key
    await page.keyboard.press('/');

    // Verify search input is now focused
    await expect(searchInput).toBeFocused();

    // Verify search input has the correct value
    await expect(searchInput).toHaveValue('/');

    // Verify search button is enabled
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeEnabled();
  });

  test('should not focus search input when pressing other keys', async ({ page }) => {
    // Verify search input is visible and not focused initially
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();
    await expect(searchInput).not.toBeFocused();

    // Press Enter key
    await page.keyboard.press('Enter');

    // Verify search input is still not focused
    await expect(searchInput).not.toBeFocused();

    // Verify search input is empty
    await expect(searchInput).toHaveValue('');

    // Press Shift key
    await page.keyboard.press('Shift');

    // Verify search input is still not focused
    await expect(searchInput).not.toBeFocused();

    // Verify search input is empty
    await expect(searchInput).toHaveValue('');
  });
});
